`,ez='<svg class="report-ornament" viewBox="0 0 100 100" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1"><circle cx="50" cy="50" r="36"/><circle cx="50" cy="50" r="25"/><ellipse cx="50" cy="50" rx="43" ry="15" transform="rotate(-35 50 50)"/><path d="M50 3V97M3 50H97M17 17L83 83M17 83L83 17" opacity=".4"/></g><path d="M50 33L54 46L67 50L54 54L50 67L46 54L33 50L46 46Z" fill="currentColor"/></svg>',eO=`
